using NetArchTest.Rules;

namespace PaymentAuthorization.ArchitectureTest.Layering;

/// <summary>
/// Guards the Domain -> Application -> Infrastructure dependency direction so that
/// no business-facing layer ends up reaching into technical/provider details.
/// </summary>
public sealed class LayerDependencyTests
{
    private const string ApplicationNamespace = "PaymentAuthorization.Application";
    private const string InfrastructureNamespace = "PaymentAuthorization.Infrastructure";

    [Fact]
    public void Domain_does_not_depend_on_application_or_infrastructure()
    {
        var result = Types.InAssembly(typeof(Domain.Money).Assembly)
            .Should()
            .NotHaveDependencyOnAny(ApplicationNamespace, InfrastructureNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        var result = Types.InAssembly(typeof(Application.IPaymentGateway).Assembly)
            .Should()
            .NotHaveDependencyOn(InfrastructureNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    private static string Describe(TestResult result) =>
        result.FailingTypes is null
            ? "Layer dependency rule failed."
            : "Layer violation(s) found in: " + string.Join(", ", result.FailingTypes.Select(t => t.FullName));
}
EOF
echo done

